const body = $json;
const phoneRaw = String(body.phone || "");
let phone = "";
for (const ch of phoneRaw) { if (ch >= "0" && ch <= "9") phone += ch; }
const oid = body.order_id || "ORD-1";
const order = { orderId: oid, customer: body.customer_name || "Pelanggan", product: body.product || "Produk", total: body.total || 0, phone: phone };
const valid = phone.startsWith("62") && phone.length >= 10 && phone.length <= 15;
if (!valid) {
  return [{ json: { error: "INVALID_PHONE", phone: phone } }];
}
return [{ json: order }];

const o = $json;
const msg = "Halo " + o.customer + "! Order " + o.orderId + " diterima. Produk: " + o.product + ". Total: Rp " + o.total + ". Kami proses segera.";
return [{ json: { target: o.phone, message: msg } }];

const r = $json;
const status = (r.status === 'success' || r.kicked) ? 'OK' : 'FAILED';
return [{ json: { status: status, resp: r } }];
